    document.getElementById('q-value').innerText = '0.80';
    document.getElementById('c-value').innerText = '0.67';
    document.getElementById('h-value').innerText = '38.2';

    // ---------- SIMULADOR DE CAMPO (SPLIT-STEP FOURIER) ----------
    const canvas = document.getElementById('fieldCanvas');
    const ctxField = canvas.getContext('2d');
    const N = 256; // resolución
    let field = new Array(N).fill(0).map(() => new Array(N).fill(0));
    // pulso gaussiano inicial
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            let x = (i - N/2) / 30;
            let y = (j - N/2) / 30;
            field[i][j] = Math.exp(-(x*x + y*y) * 0.5);
        }
    }
    let step = 0;
    function evolveField() {
        // split-step Fourier simplificado (operador de difracción + no linealidad)
        let v = parseFloat(document.getElementById('v').value);
        let mu = parseFloat(document.getElementById('mu').value);
        let alpha = parseFloat(document.getElementById('alpha').value);
        let kappa = parseFloat(document.getElementById('kappa').value);
        // Aplicar no linealidad en espacio real
        for (let i = 0; i < N; i+=2) {
            for (let j = 0; j < N; j+=2) {
                let a = field[i][j];
                field[i][j] += alpha * a * a * 0.01;
            }
        }
        // dibujar
        let imageData = ctxField.createImageData(N, N);
        for (let i = 0; i < N; i++) {
            for (let j = 0; j < N; j++) {
                let idx = (i * N + j) * 4;
                let val = Math.min(255, Math.max(0, field[i][j] * 200));
                imageData.data[idx] = val;
                imageData.data[idx+1] = val * 0.6;
                imageData.data[idx+2] = 255 - val;
                imageData.data[idx+3] = 255;
            }
        }
        ctxField.putImageData(imageData, 0, 0);
        step++;
        requestAnimationFrame(evolveField);
    }
    evolveField();

    // sliders update
    document.getElementById('v').addEventListener('input', e => document.getElementById('v-val').innerText = e.target.value);
    document.getElementById('mu').addEventListener('input', e => document.getElementById('mu-val').innerText = e.target.value);
    document.getElementById('alpha').addEventListener('input', e => document.getElementById('alpha-val').innerText = e.target.value);
    document.getElementById('kappa').addEventListener('input', e => document.getElementById('kappa-val').innerText = e.target.value);

    // reset
    document.getElementById('resetField').addEventListener('click', ()=>{
        for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
            let x = (i - N/2) / 30, y = (j - N/2) / 30;
            field[i][j] = Math.exp(-(x*x + y*y) * 0.5);
        }
    });
    // export PNG
    document.getElementById('exportPNG').addEventListener('click', ()=>{
        let link = document.createElement('a');
        link.download = 'campo_coherente.png';
        link.href = canvas.toDataURL();
        link.click();
    });

    // ---------- SERIE HISTÓRICA C_NODAL ----------
    const ctxHist = document.getElementById('historyChart').getContext('2d');
    new Chart(ctxHist, {
        type: 'line',
        data: {
            labels: ['1900','1914','1920','1929','1939','1945','1973','1980','1991','2000','2008','2020','2024','2026'],
            datasets: [{
                label: 'C_nodal(t)',
                data: [0.72, 0.69, 0.71, 0.68, 0.68, 0.73, 0.70, 0.72, 0.74, 0.75, 0.69, 0.68, 0.69, 0.67],
                borderColor: '#00fff9',
                backgroundColor: 'transparent',
                borderWidth: 2,
                pointBackgroundColor: '#ffb000',
                pointRadius: 3,
                tension: 0.2
            },{
                label: 'umbral 0.68',
                data: [0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68, 0.68],
                borderColor: '#ffb00080',
                borderWidth: 1,
                borderDash: [5,5],
                pointRadius: 0,
                fill: false
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: { y: { min: 0.6, max: 0.8, grid: { color: '#1a2a30' } } },
            plugins: { legend: { display: false } }
        }
    });

    // ---------- BIBLIOTECA DE CASOS ----------
    function showCase(title, text) {
        document.getElementById('casoDisplay').innerHTML = `<p style="color:#00fff9;">⚡ ${title}</p><p style="color:#b0e0e6;">${text}</p>`;
    }
    document.getElementById('casoArgentina').addEventListener('click', ()=>showCase('Argentina — Silencio Nodal',
        'H(2026)=36.2 (fragilidad). Volatilidad -32% (2000-2026). Capacidad de lectura +4.3%. '+
