        'Error direccional 30d: 68.5% (2015-2025). RMSE $5.892. Cobertura 68%: 70%. Análogo histórico: Roma 50 a.C. (similitud 71%).'));

    // ---------- TELEMETRÍA (simulada) ----------
    const terminal = document.getElementById('terminal');
    function addTerminal(msg) {
